window.BANCO = window.BANCO || [];
window.BANCO.push({"id": "tema5", "nombre": "Tema 5 · El Gobierno y la Administración", "bloques": [{"id": "t5-ce", "nombre": "El Gobierno en la Constitución (arts. 97 a 116)"}, {"id": "t5-ley", "nombre": "Ley 50/1997, del Gobierno"}], "calendarios": {}, "casos": [], "preguntas": [{"id": "ce-157", "origen": "oficiales", "test": "INAP mayo 2026", "n": 5, "enunciado": "De acuerdo con el artículo 112 de la Constitución Española de 1978, la cuestión de confianza planteada por el Presidente de Gobierno se entenderá otorgada cuando vote a favor de la misma:", "opciones": ["La mayoria simple del Congreso de los Diputados.", "La mayoría simple del Congreso de los Diputados y del Senado.", "La mayoría absoluta del Congreso de los Diputados.", "La mayoria absoluta del Congreso de los Diputados y del Senado."], "bloque": "t5-ce", "precepto": "Artículo 112 CE", "correcta": 0, "justificaciones": ["Es esta. Mayoría simple y solo en el Congreso: la confianza es la más barata de las mayorías.", "No. El Senado no interviene en la cuestión de confianza.", "No. La mayoría absoluta es la de la investidura en primera votación (99.3) y la de la moción de censura (113.1), no la de la confianza.", "No. Acumula los dos errores: mayoría absoluta y Senado."], "arts": [112], "citas": [{"texto": "«El Presidente del Gobierno, previa deliberación del Consejo de Ministros, puede plantear ante el Congreso de los Diputados la cuestión de confianza sobre su programa o sobre una declaración de política general. La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados.»", "fuente": "Artículo 112 CE"}], "truco": "Confianza, mayoría simple; censura, mayoría absoluta. Y las dos, solo ante el Congreso."}, {"id": "ce-163", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 5, "enunciado": "Señala el artículo 98 de la Constitución Española de 1978 que el Gobierno se compone:", "opciones": ["Del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los Secretarios de Estado.", "Del Presidente, de los Ministros y de los Secretarios de Estado.", "Del Presidente, de los Vicepresidentes, en su caso, de los Ministros, de los Secretarios de Estado y de los demás miembros que establezca la ley.", "Del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley."], "bloque": "t5-ce", "precepto": "Artículo 98.1 CE", "correcta": 3, "justificaciones": ["No. Los Secretarios de Estado no son miembros del Gobierno, y además falta la cláusula abierta.", "No. Mete a los Secretarios de Estado y se deja fuera a los Vicepresidentes.", "No. Mantiene la cláusula abierta, pero cuela a los Secretarios de Estado, que no son miembros del Gobierno.", "Es esta. Presidente, Vicepresidentes «en su caso», Ministros y los demás miembros que establezca la ley. La cláusula abierta final es parte del artículo."], "arts": [98], "citas": [{"texto": "«El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.»", "fuente": "Artículo 98.1 CE"}], "truco": "Los Secretarios de Estado son órganos superiores de la Administración General del Estado (Ley 40/2015), no miembros del Gobierno. Es la trampa favorita del 98."}, {"id": "ce-184", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 20, "enunciado": "De acuerdo con el artículo 103.1 de la Constitución Española de 1978, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los siguientes principios:", "opciones": ["Eficiencia, jerarquía, descentralización, desconcentración y coordinación.", "Eficiencia, Eficacia, jerarquía, descentralización y coordinación.", "Eficacia, jerarquía, descentralización, desconcentración y coordinación.", "Eficiencia, eficacia, jerarquía, descentralización, autonomía y coordinación."], "bloque": "t5-ce", "precepto": "Artículo 103.1 CE", "correcta": 2, "justificaciones": ["No. Cambia **eficacia** por «eficiencia». La eficiencia está en el 31.2, referida al gasto público.", "No. Mete la eficiencia y se deja fuera la desconcentración.", "Es esta. Cinco principios y en ese orden: eficacia, jerarquía, descentralización, desconcentración y coordinación.", "No. Añade eficiencia y autonomía, que no son principios del 103.1."], "arts": [103], "citas": [{"texto": "«La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.»", "fuente": "Artículo 103.1 CE"}], "marca": {"nivel": "clave", "nota": "Funciones del Gobierno (art. 97) y principios de la Administración (art. 103): en las listas y en el INAP."}, "truco": "Eficacia, no eficiencia. Y descentralización y desconcentración van siempre juntas: si falta una, la opción es falsa."}, {"id": "ce-185", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 24, "enunciado": "De acuerdo con el artículo 103 de la Constitución Española de 1978, la ley regulará el estatuto de los funcionarios públicos y el acceso a la función pública de acuerdo con los principios de:", "opciones": ["Mérito y capacidad.", "Objetividad y concurrencia competitiva.", "Mérito, objetividad y concurrencia competitiva.", "Mérito, capacidad, objetividad y concurrencia competitiva."], "bloque": "t5-ce", "precepto": "Artículo 103.3 CE", "correcta": 0, "justificaciones": ["Es esta. Solo dos: mérito y capacidad.", "No. Ni la objetividad ni la concurrencia competitiva aparecen en el 103.3.", "No. Sobran la objetividad y la concurrencia competitiva.", "No. Mérito y capacidad son los dos correctos; los otros dos son añadidos."], "arts": [103], "citas": [{"texto": "«La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de mérito y capacidad, las peculiaridades del ejercicio de su derecho a sindicación, el sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones.»", "fuente": "Artículo 103.3 CE"}], "marca": {"nivel": "clave", "nota": "Funciones del Gobierno (art. 97) y principios de la Administración (art. 103): en las listas y en el INAP."}, "truco": "En el acceso, la Constitución solo pone dos principios (103.3). La igualdad viene del 23.2 y la publicidad, del TREBEP. Si la opción suma tres o cuatro, es falsa."}, {"id": "ce-198", "origen": "oficiales", "test": "INAP feb 2022", "n": 4, "enunciado": "Según el artículo 99 de la CE, ¿quién propone un candidato a la Presidencia del Gobierno después de cada renovación del Congreso de los Diputados, y en los demás supuestos constitucionales en que así proceda?", "opciones": ["El partido político con mayor representación en el Congreso de los Diputados.", "Lo hacen por consenso las Mesas del Congreso y del Senado.", "El Presidente del Congreso.", "El Rey."], "bloque": "t5-ce", "precepto": "Artículo 99.1 CE", "correcta": 3, "justificaciones": ["No. La Constitución no dice nada del partido más votado: no hay automatismo.", "No. Las Mesas de las Cámaras no proponen candidato.", "No. El Presidente del Congreso es el cauce («a través del»), no el que propone.", "Es esta. Propone el Rey, después de consultar a los grupos y usando al Presidente del Congreso como canal."], "arts": [99], "citas": [{"texto": "«Después de cada renovación del Congreso de los Diputados, y en los demás supuestos constitucionales en que así proceda, el Rey, previa consulta con los representantes designados por los Grupos políticos con representación parlamentaria, y a través del Presidente del Congreso, propondrá un candidato a la Presidencia del Gobierno.»", "fuente": "Artículo 99.1 CE"}], "marca": {"nivel": "estrella", "nota": "La investidura del artículo 99 (plazos, mayorías y los dos meses) está en las listas y ha caído en el INAP."}, "truco": "El Presidente del Congreso es el cartero, no el remitente. Y el resto del 99: mayoría absoluta en primera votación, simple 48 horas después, y a los dos meses sin investidura, disolución automática."}, {"id": "ce-300", "origen": "otras", "test": "Test Tema 5", "n": 3, "enunciado": "Según el artículo 100 de la Constitución Española, ¿quién nombra a los Ministros?", "opciones": ["El Presidente del Gobierno.", "El Presidente del Congreso.", "La Comisión de Nombramientos de las Cortes Generales.", "El Rey."], "bloque": "t5-ce", "precepto": "Artículo 100 CE", "correcta": 3, "justificaciones": ["No. El Presidente del Gobierno propone, no nombra.", "No. El Presidente del Congreso no interviene en este nombramiento.", "No. No existe tal Comisión de Nombramientos.", "Es esta. Literal del artículo 100: nombra el Rey, a propuesta del Presidente del Gobierno."], "arts": [100], "citas": [{"texto": "«Los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de su Presidente.»", "fuente": "Artículo 100 CE"}], "truco": "El mismo esquema del artículo 62.e): el Rey nombra y separa a los miembros del Gobierno, siempre a propuesta de su Presidente."}, {"id": "ce-301", "origen": "otras", "test": "Test Tema 5", "n": 1, "enunciado": "El artículo 12.2 de la Ley 50/1997, de 27 de noviembre, del Gobierno, dispone que los Vicepresidentes y los Ministros son nombrados y separados por:", "opciones": ["El Rey, a propuesta del Presidente del Gobierno.", "El Congreso de los Diputados, a propuesta del Presidente del Gobierno.", "El Presidente del Gobierno, a propuesta de las Cortes Generales.", "El Presidente del Gobierno, a propuesta del Rey."], "bloque": "t5-ley", "precepto": "Artículo 12.2 · Ley 50/1997, de 27 de noviembre, del Gobierno", "correcta": 0, "justificaciones": ["Es esta. Mismo esquema que el artículo 100 CE, ahora recogido en la Ley del Gobierno: nombra el Rey, propone el Presidente.", "No. El Congreso no interviene en el nombramiento de los miembros del Gobierno.", "No. Invierte los papeles: no es el Presidente quien nombra.", "No. Tampoco: el Presidente propone, el Rey nombra, nunca al revés."], "arts": [], "citas": [{"texto": "«Los Vicepresidentes y Ministros serán nombrados y separados por el Rey, a propuesta del Presidente del Gobierno.»", "fuente": "Artículo 12.2 · Ley 50/1997, de 27 de noviembre, del Gobierno"}]}, {"id": "ce-302", "origen": "otras", "test": "Test Tema 5", "n": 2, "enunciado": "Según el artículo 113 de la Constitución Española, la moción de censura contra el Gobierno:", "opciones": ["Deberá ser propuesta al menos por la décima parte de los Diputados y exige para su adopción mayoría absoluta.", "Se plantea por el Presidente del Gobierno y exige para entenderse otorgada mayoría simple.", "Deberá ser propuesta al menos por la quinta parte de los Diputados y exige mayoría absoluta.", "Podrá votarse el mismo día de su presentación."], "bloque": "t5-ce", "precepto": "Artículo 113.1 y 113.2 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 113: décima parte de los Diputados y mayoría absoluta para su adopción.", "No. La censura no la plantea el Presidente del Gobierno (eso es la cuestión de confianza del artículo 112), y ahí sí basta la mayoría simple.", "No. La fracción exigida es un décimo, no un quinto, de los Diputados.", "No. El artículo 113.3 exige que no pueda votarse hasta que transcurran cinco días desde su presentación."], "arts": [113], "citas": [{"texto": "«El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción por mayoría absoluta de la moción de censura. La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.»", "fuente": "Artículo 113.1 y 113.2 CE"}], "marca": {"nivel": "clave", "nota": "La moción de censura: proponerla, votarla y qué pasa si sale."}, "truco": "Censura: la proponen los Diputados (décima parte) y exige mayoría absoluta. Confianza: la plantea el Presidente del Gobierno y basta mayoría simple. No mezclar los dos mecanismos."}, {"id": "ce-303", "origen": "otras", "test": "Test Tema 5", "n": 5, "enunciado": "El artículo 108 de la Constitución Española dispone que el Gobierno responde en su gestión política:", "opciones": ["Solidariamente ante el Congreso de los Diputados.", "Solidariamente ante el Congreso de los Diputados y ante el Senado.", "Solidariamente ante el Rey.", "Solidariamente ante el Consejo de Ministros."], "bloque": "t5-ce", "precepto": "Artículo 108 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 108: la responsabilidad política se exige solo ante el Congreso.", "No. El Senado queda fuera de este control político.", "No. El Rey no es un órgano de control político del Gobierno.", "No. El Consejo de Ministros es un órgano del propio Gobierno, no quien le exige responsabilidad."], "arts": [108], "citas": [{"texto": "«El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados.»", "fuente": "Artículo 108 CE"}], "truco": "El control político del Gobierno (moción de censura, cuestión de confianza, responsabilidad solidaria del artículo 108) se concentra siempre en el Congreso, nunca en el Senado."}, {"id": "ce-304", "origen": "otras", "test": "Test Tema 5", "n": 4, "enunciado": "De las siguientes funciones recogidas en la Ley 50/1997, de 27 de noviembre, del Gobierno, ¿cuál corresponde al Consejo de Ministros?", "opciones": ["Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios.", "Dirigir la política de defensa y ejercer respecto de las Fuerzas Armadas las funciones previstas en la legislación reguladora.", "Crear, modificar y suprimir los órganos directivos de los Departamentos Ministeriales.", "Representar al Gobierno."], "bloque": "t5-ley", "precepto": "Artículo 5.1.i · Ley 50/1997; Artículo 2.2 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Resolver los conflictos entre Ministerios es función del Presidente (2.2.l), no del Consejo de Ministros.", "No. Dirigir la política de defensa también es del Presidente (2.2.f).", "Es esta. Crear, modificar y suprimir los órganos directivos (las unidades de dentro de cada Departamento) es función del Consejo de Ministros; crear o suprimir Departamentos enteros, en cambio, es del Presidente (art. 2.2.j).", "No. Representar al Gobierno también corresponde al Presidente (2.2.a)."], "arts": [], "citas": [{"texto": "«Al Consejo de Ministros, como órgano colegiado del Gobierno, le corresponde el ejercicio de las siguientes funciones: … i) Crear, modificar y suprimir los órganos directivos de los Departamentos Ministeriales.»", "fuente": "Artículo 5.1.i · Ley 50/1997"}, {"texto": "«En todo caso, corresponde al Presidente del Gobierno: a) Representar al Gobierno … f) Dirigir la política de defensa … l) Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios.»", "fuente": "Artículo 2.2 · Ley 50/1997"}], "truco": "El Presidente decide sobre los Departamentos como bloques (crearlos, dirigir su política, resolver sus conflictos); el Consejo de Ministros entra en el escalón inferior: los órganos directivos dentro de cada Departamento."}, {"id": "ce-305", "origen": "otras", "test": "Test Tema 5", "n": 6, "enunciado": "Según el artículo 2 de la Ley 50/1997, de 27 de noviembre, del Gobierno, corresponde en todo caso al Presidente del Gobierno:", "opciones": ["Aprobar el Proyecto de Ley de Presupuestos Generales del Estado.", "Establecer el programa político del Gobierno y determinar las directrices de la política interior y exterior.", "Declarar los estados de alarma y de excepción.", "Acordar la negociación y firma de Tratados internacionales."], "bloque": "t5-ley", "precepto": "Artículo 2.2.b · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Aprobar los Presupuestos es función del Consejo de Ministros como órgano colegiado (art. 5.1.b).", "Es esta. Literal del artículo 2.2.b.", "No. Declarar los estados de alarma y excepción también es del Consejo de Ministros (art. 5.1.f).", "No. Acordar la negociación y firma de Tratados internacionales corresponde igualmente al Consejo de Ministros (art. 5.1.d)."], "arts": [], "citas": [{"texto": "«En todo caso, corresponde al Presidente del Gobierno: … b) Establecer el programa político del Gobierno y determinar las directrices de la política interior y exterior y velar por su cumplimiento.»", "fuente": "Artículo 2.2.b · Ley 50/1997"}], "truco": "Presupuestos, estados de alarma/excepción y Tratados internacionales: siempre Consejo de Ministros, órgano colegiado. Fijar el rumbo político del Gobierno: el Presidente, en solitario."}, {"id": "ce-306", "origen": "otras", "test": "Test Tema 5", "n": 12, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, los Vicepresidentes:", "opciones": ["Han de ser siempre también Ministros.", "Asisten al Consejo de Ministros, pero no son miembros del Gobierno.", "Pueden ser Ministros o no.", "No asisten a las reuniones del Consejo de Ministros."], "bloque": "t5-ley", "precepto": "Artículo 3.2 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. No siempre: solo cuando además asumen la titularidad de un Departamento.", "No. El artículo 1.2 los incluye expresamente entre los miembros del Gobierno.", "Es esta. El artículo 3.2 solo añade la condición de Ministro cuando el Vicepresidente asume un Departamento; si no lo asume, es Vicepresidente sin ser Ministro. Por tanto, pueden ser Ministros o no.", "No. No hay ninguna norma que se lo impida; forman parte del Gobierno que se reúne en Consejo de Ministros."], "arts": [], "citas": [{"texto": "«El Vicepresidente que asuma la titularidad de un Departamento Ministerial ostentará, además, la condición de Ministro.»", "fuente": "Artículo 3.2 · Ley 50/1997"}]}, {"id": "ce-307", "origen": "otras", "test": "Test Tema 5", "n": 9, "enunciado": "Según el artículo 1 de la Ley 50/1997, de 27 de noviembre, del Gobierno, el Gobierno se compone de:", "opciones": ["El Presidente, el Vicepresidente o Vicepresidentes, en su caso, y los Ministros.", "El Presidente, el Vicepresidente o Vicepresidentes, el Consejo de Ministros y las Comisiones Delegadas del Gobierno.", "El Presidente, los Ministros y los Secretarios de Estado.", "El Presidente, los Vicepresidentes, los Ministros y los Secretarios de Estado."], "bloque": "t5-ley", "precepto": "Artículo 1.2 y 1.3 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Solo tres piezas son miembros del Gobierno; el Consejo de Ministros y las Comisiones Delegadas no son un cuarto y un quinto miembro, sino las formas en que esos miembros se reúnen.", "No. Confunde a los miembros del Gobierno con los órganos en que se reúnen.", "No. Los Secretarios de Estado nunca son miembros del Gobierno: son órganos de colaboración y apoyo (art. 7).", "No. Tampoco: mismo error con los Secretarios de Estado."], "arts": [], "citas": [{"texto": "«El Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros. Los miembros del Gobierno se reúnen en Consejo de Ministros y en Comisiones Delegadas del Gobierno.»", "fuente": "Artículo 1.2 y 1.3 · Ley 50/1997"}], "truco": "Igual que en el artículo 98.1 CE: los Secretarios de Estado quedan siempre fuera. Y aquí, además, no conviertas al Consejo de Ministros en un miembro más: es el órgano donde los miembros se reúnen."}, {"id": "ce-308", "origen": "otras", "test": "Examen Tema 5", "n": 10, "enunciado": "De conformidad con el artículo 13 de la Ley 50/1997, de 27 de noviembre, del Gobierno, en los casos de vacante, ausencia o enfermedad, la suplencia de los Ministros para el despacho ordinario de los asuntos de su competencia:", "opciones": ["Recaerá en el Subsecretario del Ministerio de que se trate.", "Recaerá en los Secretarios de Estado del Ministerio, según determine el Real Decreto de estructura de ese Ministerio.", "Será determinada por Real Decreto del Presidente del Gobierno, debiendo recaer, en todo caso, en otro miembro del Gobierno.", "Será determinada por el propio Ministro saliente."], "bloque": "t5-ley", "precepto": "Artículo 13.2 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. El Subsecretario no es miembro del Gobierno.", "No. Tampoco lo son los Secretarios de Estado.", "Es esta. Literal del artículo 13.2: decide el Presidente, y el sustituto tiene que ser otro miembro del Gobierno (otro Ministro o un Vicepresidente), nunca un Secretario de Estado ni un Subsecretario.", "No. El propio Ministro no se autodesigna sustituto: la decisión es del Presidente."], "arts": [], "citas": [{"texto": "«La suplencia de los Ministros, para el despacho ordinario de los asuntos de su competencia, será determinada por Real Decreto del Presidente del Gobierno, debiendo recaer, en todo caso, en otro miembro del Gobierno.»", "fuente": "Artículo 13.2 · Ley 50/1997"}], "truco": "No confundir con la suplencia del propio Presidente del Gobierno (art. 13.1), que recae en los Vicepresidentes por orden de prelación y, en su defecto, en los Ministros por orden de precedencia, sin necesidad de ningún Real Decreto."}, {"id": "ce-309", "origen": "otras", "test": "Test exámenes", "n": 251, "enunciado": "Según el artículo 5 de la Ley 50/1997, de 27 de noviembre, del Gobierno, las deliberaciones del Consejo de Ministros:", "opciones": ["Serán públicas.", "Serán secretas.", "Serán públicas, salvo que concurran razones justificadas de interés general.", "Serán secretas, salvo que concurran razones de interés público."], "bloque": "t5-ley", "precepto": "Artículo 5.3 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. El precepto no habla de publicidad en ningún caso.", "Es esta. Literal del artículo 5.3, sin matices ni excepciones.", "No. Tampoco admite excepción alguna a favor de la publicidad.", "No. El secreto no admite excepción por razones de interés público: es la regla, sin condición."], "arts": [], "citas": [{"texto": "«Las deliberaciones del Consejo de Ministros serán secretas.»", "fuente": "Artículo 5.3 · Ley 50/1997"}], "truco": "El mismo secreto rige para las Comisiones Delegadas (art. 6.5); la Comisión General de Secretarios de Estado y Subsecretarios usa, en cambio, la palabra «reservadas» (art. 8.4)."}, {"id": "ce-320", "origen": "otras", "test": "Test exámenes", "n": 227, "enunciado": "Según el artículo 24.2 de la Ley 50/1997, de 27 de noviembre, del Gobierno, los reglamentos se ordenarán según la siguiente jerarquía:", "opciones": ["1.º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o acordado en el Consejo de Ministros. 2.º Disposiciones aprobadas por Orden Ministerial.", "1.º Disposiciones aprobadas por Real Decreto del Consejo de Ministros. 2.º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno. 3.º Órdenes Ministeriales.", "1.º Reales Decretos Legislativos y Reales Decretos-leyes. 2.º Reales Decretos del Presidente del Gobierno. 3.º Reales Decretos del Consejo de Ministros.", "1.º Real Decreto del Presidente del Gobierno. 2.º Real Decreto del Consejo de Ministros. 3.º Orden Ministerial."], "bloque": "t5-ley", "precepto": "Artículo 24.2 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 24.2: solo dos escalones, y el primero junta al Presidente y al Consejo de Ministros al mismo nivel.", "No. Separa en dos niveles distintos lo que el precepto pone en un único primer escalón, y añade un tercero que no existe.", "No. Mezcla la jerarquía de los reglamentos con la lista, distinta, de las FORMAS de las decisiones del Gobierno (art. 24.1), que sí incluye los Reales Decretos Legislativos y Reales Decretos-leyes.", "No. Separa indebidamente al Presidente del Consejo de Ministros, que comparten el primer escalón."], "arts": [], "citas": [{"texto": "«Los reglamentos se ordenarán según la siguiente jerarquía: 1.º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o acordado en el Consejo de Ministros. 2.º Disposiciones aprobadas por Orden Ministerial.»", "fuente": "Artículo 24.2 · Ley 50/1997"}], "truco": "No confundir la jerarquía de los REGLAMENTOS (art. 24.2, solo dos escalones) con la lista más larga de las FORMAS que pueden revestir las decisiones del Gobierno (art. 24.1, hasta seis: Reales Decretos Legislativos y Reales Decretos-leyes, Reales Decretos del Presidente, Reales Decretos del Consejo de Ministros, Acuerdos del Consejo de Ministros, Acuerdos de Comisiones Delegadas y Órdenes Ministeriales)."}, {"id": "ce-321", "origen": "otras", "test": "Examen Tema 5", "n": 29, "enunciado": "Según el artículo 24.1 de la Ley 50/1997, de 27 de noviembre, del Gobierno, la disposición o resolución que afecte a varios Departamentos Ministeriales revestirá la forma de:", "opciones": ["Real Decreto acordado en Consejo de Ministros.", "Decreto del Presidente del Gobierno.", "Real Decreto del Ministro más antiguo en el cargo.", "Orden del Ministro de la Presidencia, dictada a propuesta de los Ministros interesados."], "bloque": "t5-ley", "precepto": "Artículo 24.1.f · Ley 50/1997", "correcta": 3, "justificaciones": ["No. El Real Decreto acordado en Consejo de Ministros es la forma de las decisiones de ese órgano colegiado (24.1.c), no la de una disposición conjunta de varios Ministros.", "No. No existe la figura de un «Decreto» simple del Presidente; su forma propia es el Real Decreto (24.1.b).", "No. La ley no atiende a la antigüedad del Ministro, sino a que la disposición afecte a varios Departamentos.", "Es esta. Literal del artículo 24.1.f: cuando varios Departamentos están implicados, la Orden la firma el Ministro de la Presidencia, a propuesta de los Ministros afectados."], "arts": [], "citas": [{"texto": "«Órdenes Ministeriales, las disposiciones y resoluciones de los Ministros. Cuando la disposición o resolución afecte a varios Departamentos revestirá la forma de Orden del Ministro de la Presidencia, dictada a propuesta de los Ministros interesados.»", "fuente": "Artículo 24.1.f · Ley 50/1997"}], "truco": "Una Orden Ministerial normal la firma el titular del Departamento; si afecta a varios Departamentos a la vez, la firma siempre el Ministro de la Presidencia, a propuesta de los interesados."}, {"id": "ce-322", "origen": "otras", "test": "Test exámenes", "n": 228, "enunciado": "Señale cuáles son los órganos de colaboración y apoyo del Gobierno, según la Ley 50/1997, de 27 de noviembre, del Gobierno:", "opciones": ["Los Ministros y Secretarios de Estado.", "Los Secretarios de Estado, la Comisión General de Secretarios de Estado y Subsecretarios, el Secretariado del Gobierno y los Gabinetes.", "Los Vicepresidentes del Gobierno.", "Los Subsecretarios y los Secretarios Generales Técnicos."], "bloque": "t5-ley", "precepto": "Capítulo II del Título I · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Los Ministros son miembros del Gobierno (art. 1.2), no un órgano de colaboración y apoyo.", "Es esta. Esos cuatro son, exactamente, los cuatro artículos del Capítulo II: Secretarios de Estado, Comisión General de Secretarios de Estado y Subsecretarios, Secretariado del Gobierno y Gabinetes.", "No. Los Vicepresidentes también son miembros del Gobierno.", "No. Los Subsecretarios y Secretarios Generales Técnicos pertenecen a la Administración General del Estado, no son de los cuatro órganos que regula este capítulo."], "arts": [], "citas": [{"texto": "«CAPÍTULO II. De los órganos de colaboración y apoyo del Gobierno. Artículo 7. De los Secretarios de Estado. Artículo 8. De la Comisión General de Secretarios de Estado y Subsecretarios. Artículo 9. Del Secretariado del Gobierno. Artículo 10. De los Gabinetes.»", "fuente": "Capítulo II del Título I · Ley 50/1997"}], "truco": "Miembros del Gobierno (Presidente, Vicepresidentes, Ministros) frente a órganos de colaboración y apoyo (Secretarios de Estado, Comisión General de SEyS, Secretariado del Gobierno, Gabinetes): son dos listas distintas y no se mezclan."}, {"id": "ce-323", "origen": "otras", "test": "Test exámenes", "n": 229, "enunciado": "Señale la afirmación correcta. De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, los Secretarios de Estado:", "opciones": ["Dirigen los servicios comunes del Departamento ministerial.", "Examinan cuestiones de carácter general relacionadas con su Departamento ministerial.", "Son los titulares de los órganos directivos encargados de la gestión de las áreas del Ministerio correspondiente.", "Son órganos superiores directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica."], "bloque": "t5-ley", "precepto": "Artículo 7.1 · Ley 50/1997", "correcta": 3, "justificaciones": ["No. Dirigir los servicios comunes de un Ministerio es función del Subsecretario, no del Secretario de Estado.", "No. Examinar cuestiones generales que afecten a varios Departamentos es función de la Comisión General de Secretarios de Estado y Subsecretarios (art. 8.5.b), no una función individual del Secretario de Estado.", "No. Ser titular de los órganos directivos de gestión describe más bien a un Director General, no al Secretario de Estado, que es un órgano superior, no directivo.", "Es esta. Literal del artículo 7.1."], "arts": [], "citas": [{"texto": "«Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica de un Departamento o de la Presidencia del Gobierno.»", "fuente": "Artículo 7.1 · Ley 50/1997"}], "truco": "Órganos superiores (Ministros y Secretarios de Estado) frente a órganos directivos (Subsecretarios, Secretarios Generales, Directores Generales…): los primeros fijan la política, los segundos la gestionan."}, {"id": "ce-324", "origen": "otras", "test": "Test exámenes", "n": 232, "enunciado": "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, los Gabinetes:", "opciones": ["Son órganos de apoyo político y técnico del Presidente del Gobierno, de los Vicepresidentes, de los Ministros y de los Secretarios de Estado.", "Son órganos de apoyo político y técnico del Presidente, Vicepresidentes, Ministros, Secretarios de Estado, Subsecretarios y Directores Generales.", "Son órganos de apoyo político y técnico del Presidente, Vicepresidentes, Ministros, Secretarios de Estado, Subsecretarios y Secretarios Generales.", "Son órganos cuyos miembros pueden adoptar actos o resoluciones que correspondan a órganos de la Administración General del Estado."], "bloque": "t5-ley", "precepto": "Artículo 10.1 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 10.1: cuatro cargos, ni uno más.", "No. Añade a Subsecretarios y Directores Generales, que no tienen Gabinete propio en este artículo.", "No. Añade a Subsecretarios y Secretarios Generales, igualmente fuera de la lista.", "No. Es justo lo contrario: el propio artículo 10.1 dice que sus miembros NO pueden adoptar actos o resoluciones que correspondan legalmente a los órganos de la Administración General del Estado."], "arts": [], "citas": [{"texto": "«Los Gabinetes son órganos de apoyo político y técnico del Presidente del Gobierno, de los Vicepresidentes, de los Ministros y de los Secretarios de Estado.»", "fuente": "Artículo 10.1 · Ley 50/1997"}]}, {"id": "ce-325", "origen": "otras", "test": "Examen Tema 5", "n": 16, "enunciado": "Señale la afirmación INCORRECTA en relación con la Comisión General de Secretarios de Estado y Subsecretarios, de acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno:", "opciones": ["Le corresponde el análisis de una Orden del Ministro de la Presidencia que afecta a varios Departamentos.", "Puede adoptar acuerdos por delegación del Gobierno.", "Podrá asistir a sus reuniones el Director del Gabinete del Presidente del Gobierno, en función de la materia.", "Podrá asistir a sus reuniones la persona titular de la Secretaría General de Financiación Autonómica y Local, en función de la materia."], "bloque": "t5-ley", "precepto": "Artículo 8.4 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Sí le corresponde: el examen de los asuntos que vayan a someterse al Consejo de Ministros, incluidas las Órdenes que afecten a varios Departamentos (art. 8.5).", "Es esta. El propio artículo 8.4 lo prohíbe expresamente: la Comisión nunca puede adoptar acuerdos por delegación del Gobierno, solo examinar y preparar los asuntos que luego decide el Consejo de Ministros.", "No. El artículo 8.1 permite la asistencia de altos cargos convocados por razón de la materia, entre ellos el Director del Gabinete de la Presidencia.", "No. Igualmente permitido por el artículo 8.1 cuando la materia lo justifique."], "arts": [], "citas": [{"texto": "«Las deliberaciones de la Comisión General de Secretarios de Estado y Subsecretarios serán reservadas. En ningún caso la Comisión podrá adoptar decisiones o acuerdos por delegación del Gobierno.»", "fuente": "Artículo 8.4 · Ley 50/1997"}], "truco": "La Comisión General de Secretarios de Estado y Subsecretarios «filtra» los asuntos antes del Consejo de Ministros, pero nunca decide en su lugar: no tiene poder de delegación."}, {"id": "ce-326", "origen": "otras", "test": "Examen Tema 5", "n": 7, "enunciado": "Según el artículo 18 de la Ley 50/1997, de 27 de noviembre, del Gobierno, que regula el funcionamiento del Consejo de Ministros, ¿quién actúa como Secretario de las reuniones de este órgano colegiado?", "opciones": ["El Vicepresidente Primero.", "El Ministro portavoz del Gobierno.", "El Ministro de la Presidencia.", "El Ministro de Justicia."], "bloque": "t5-ley", "precepto": "Artículo 18.1 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. El Vicepresidente Primero no tiene asignada esta función por la Ley.", "No. El portavoz del Gobierno es un cargo político distinto, sin funciones de Secretaría del Consejo.", "Es esta. Literal del artículo 18.1: convoca y preside el Presidente del Gobierno, y actúa como Secretario el Ministro de la Presidencia.", "No. El Ministro de Justicia tampoco ejerce esta secretaría."], "arts": [], "citas": [{"texto": "«El Presidente del Gobierno convoca y preside las reuniones del Consejo de Ministros, actuando como Secretario el Ministro de la Presidencia.»", "fuente": "Artículo 18.1 · Ley 50/1997"}], "truco": "Mismo apellido que el Secretariado del Gobierno (art. 9), que es precisamente el órgano de apoyo que asiste al Ministro-Secretario del Consejo de Ministros."}, {"id": "ce-327", "origen": "otras", "test": "Examen Tema 5", "n": 12, "enunciado": "Según lo dispuesto en el artículo 5.2 de la Ley 50/1997, de 27 de noviembre, del Gobierno, a las reuniones del Consejo de Ministros:", "opciones": ["Deberán asistir los Secretarios de Estado en supuestos de vacante, ausencia o enfermedad del Ministro correspondiente.", "Podrán asistir los Secretarios de Estado y, excepcionalmente, otros altos cargos, cuando sean convocados para ello.", "No podrán asistir los Secretarios de Estado, pero sí otros altos cargos, cuando sean convocados.", "Solo podrán asistir los Ministros y, en su caso, el Rey."], "bloque": "t5-ley", "precepto": "Artículo 5.2 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. No es obligatoria ni está condicionada a una vacante o ausencia: es una asistencia ordinaria y potestativa.", "Es esta. Literal del artículo 5.2: asistencia posible, no obligatoria, y para altos cargos ajenos al Gobierno, excepcional.", "No. Los Secretarios de Estado sí pueden asistir, no están excluidos.", "No. El Rey preside el Consejo de Ministros solo cuando lo estima oportuno, a petición del Presidente del Gobierno, para ser informado (no está entre quienes «solo» pueden asistir) y los Secretarios de Estado también pueden hacerlo."], "arts": [], "citas": [{"texto": "«A las reuniones del Consejo de Ministros podrán asistir los Secretarios de Estado y excepcionalmente otros altos cargos, cuando sean convocados para ello, sin perjuicio de lo dispuesto en los tratados internacionales válidamente celebrados por España.»", "fuente": "Artículo 5.2 · Ley 50/1997"}]}, {"id": "ce-328", "origen": "otras", "test": "Examen Tema 5", "n": 25, "enunciado": "Según el artículo 6 de la Ley 50/1997, de 27 de noviembre, del Gobierno, la creación, modificación y supresión de las Comisiones Delegadas del Gobierno será acordada por:", "opciones": ["El Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno.", "El Presidente del Gobierno mediante Real Decreto.", "El Consejo de Ministros por Orden Delegada.", "El Presidente del Gobierno por Orden Delegada."], "bloque": "t5-ley", "precepto": "Artículo 6.1 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 6.1: decide el Consejo de Ministros, pero solo a propuesta del Presidente.", "No. El Presidente propone, pero no decide en solitario: hace falta el acuerdo del Consejo de Ministros.", "No. No existe la figura de la «Orden Delegada» para esto: es un Real Decreto.", "No. Mismo error de forma, además de atribuirlo al Presidente en solitario."], "arts": [], "citas": [{"texto": "«La creación, modificación y supresión de las Comisiones Delegadas del Gobierno será acordada por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno.»", "fuente": "Artículo 6.1 · Ley 50/1997"}], "truco": "Propone el Presidente, decide el Consejo de Ministros, y siempre mediante Real Decreto: nunca una Comisión Delegada nace por decisión unilateral del Presidente."}, {"id": "ce-329", "origen": "otras", "test": "Examen Tema 5", "n": 15, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, ¿cuál de las siguientes competencias del Consejo de Ministros es susceptible de delegación?", "opciones": ["El nombramiento de un alto cargo atribuido al Consejo de Ministros.", "Una competencia atribuida directamente por la Constitución.", "El desempeño de una función administrativa propia del Consejo de Ministros en una Comisión Delegada del Gobierno.", "Una competencia atribuida por una ley que prohíba expresamente la delegación."], "bloque": "t5-ley", "precepto": "Artículo 20.2 y 20.3 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. El nombramiento de altos cargos por el Consejo de Ministros es, precisamente, indelegable (20.3.b).", "No. Lo atribuido directamente por la Constitución tampoco se puede delegar (20.3.a).", "Es esta. Es la única vía de delegación que la Ley reconoce expresamente para el Consejo de Ministros: sus funciones administrativas, hacia las Comisiones Delegadas.", "No. Si una ley prohíbe expresamente la delegación, no cabe delegar en ningún caso (20.3.d)."], "arts": [], "citas": [{"texto": "«Son delegables a propuesta del Presidente del Gobierno las funciones administrativas del Consejo de Ministros en las Comisiones Delegadas del Gobierno. No son en ningún caso delegables: a) Las atribuidas directamente por la Constitución. b) Las relativas al nombramiento y separación de los altos cargos atribuidas al Consejo de Ministros. […] d) Las atribuidas por una ley que prohíba expresamente la delegación.»", "fuente": "Artículo 20.2 y 20.3 · Ley 50/1997"}], "truco": "El artículo 20 cierra con una lista de cuatro competencias jamás delegables: las de la Constitución, los nombramientos de altos cargos del Consejo de Ministros, las de los órganos colegiados del Gobierno (salvo la excepción de las Comisiones Delegadas) y las que una ley prohíba delegar expresamente."}, {"id": "ce-330", "origen": "otras", "test": "Examen Tema 5", "n": 19, "enunciado": "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, el Plan Anual Normativo estará coordinado por:", "opciones": ["El Consejo de Ministros.", "La Abogacía General del Estado.", "El Consejo de Estado.", "El Ministerio de la Presidencia."], "bloque": "t5-ley", "precepto": "Artículo 25.4 · Ley 50/1997", "correcta": 3, "justificaciones": ["No. El Consejo de Ministros aprueba el Plan, pero no es quien lo coordina.", "No. La Abogacía General del Estado no interviene en esta función.", "No. El Consejo de Estado tampoco: su papel es emitir dictamen, no coordinar el Plan.", "Es esta. Literal del artículo 25.4: coordina el Ministerio de la Presidencia, aunque la aprobación final sea del Consejo de Ministros."], "arts": [], "citas": [{"texto": "«El Plan Anual Normativo estará coordinado por el Ministerio de la Presidencia, con el objeto de asegurar la congruencia de todas las iniciativas que se tramiten […]. El Ministro de la Presidencia elevará el Plan al Consejo de Ministros para su aprobación antes del 30 de abril.»", "fuente": "Artículo 25.4 · Ley 50/1997"}]}, {"id": "ce-331", "origen": "otras", "test": "Examen Tema 5", "n": 21, "enunciado": "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, un reglamento aprobado por el Gobierno que imponga nuevas obligaciones a las personas físicas o jurídicas que desempeñen una actividad económica o profesional, como consecuencia del ejercicio de ésta, entrará en vigor, salvo excepciones justificadas:", "opciones": ["El día 2 de enero o el 1 de julio siguientes a su aprobación.", "El día 1 de enero o el 1 de julio siguientes a su aprobación.", "El día siguiente a su publicación en el Boletín Oficial del Estado.", "El día 1 de enero o el 2 de julio siguientes a su aprobación."], "bloque": "t5-ley", "precepto": "Artículo 23 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 23: 2 de enero o 1 de julio, nunca el 1 de enero ni el 2 de julio.", "No. Cambia el 2 de enero por el 1 de enero.", "No. Es la regla general de entrada en vigor (Código Civil), pero no la especial de este artículo para obligaciones a actividades económicas.", "No. Invierte las dos fechas: no es 1 de enero ni 2 de julio."], "arts": [], "citas": [{"texto": "«Las disposiciones de entrada en vigor de las leyes o reglamentos, cuya aprobación o propuesta corresponda al Gobierno o a sus miembros, y que impongan nuevas obligaciones a las personas físicas o jurídicas que desempeñen una actividad económica o profesional como consecuencia del ejercicio de ésta, preverán el comienzo de su vigencia el 2 de enero o el 1 de julio siguientes a su aprobación.»", "fuente": "Artículo 23 · Ley 50/1997"}], "truco": "Las dos fechas «raras» del calendario normativo son el 2 de enero y el 1 de julio, no el 1 de enero (Año Nuevo) ni el 2 de julio: la Ley busca fechas simbólicamente neutras, justo después de las más señaladas."}, {"id": "ce-332", "origen": "otras", "test": "Examen Tema 5", "n": 4, "enunciado": "La responsabilidad criminal del Presidente y de los demás miembros del Gobierno será exigible, en su caso, ante:", "opciones": ["El Tribunal Constitucional.", "La Sala de lo Penal del Tribunal Supremo.", "La Sala de lo Penal de la Audiencia Nacional.", "Una sala especial creada al efecto en el Tribunal Supremo."], "bloque": "t5-ce", "precepto": "Artículo 102.1 CE", "correcta": 1, "justificaciones": ["No. El Tribunal Constitucional no tiene función jurisdiccional penal.", "Es esta. Literal del artículo 102.1.", "No. No es la Audiencia Nacional, sino el Tribunal Supremo.", "No. No se crea una sala especial: es la Sala de lo Penal ordinaria del Tribunal Supremo, la misma que aforó a Diputados y Senadores."], "arts": [102], "citas": [{"texto": "«La responsabilidad criminal del Presidente y los demás miembros del Gobierno será exigible, en su caso, ante la Sala de lo Penal del Tribunal Supremo.»", "fuente": "Artículo 102.1 CE"}], "truco": "Mismo aforamiento que Diputados y Senadores (art. 71.3 CE) y que los Magistrados del Tribunal Constitucional (art. 26 LOTC): Sala de lo Penal del Tribunal Supremo."}, {"id": "ce-333", "origen": "otras", "test": "Examen Tema 5", "n": 24, "enunciado": "Según el artículo 102 de la Constitución Española, si el Presidente del Gobierno fuere acusado de un delito contra la seguridad del Estado en el ejercicio de sus funciones, la iniciativa sólo podrá ser planteada por:", "opciones": ["La quinta parte de los miembros del Congreso y aprobada con mayoría simple.", "La cuarta parte de los miembros del Congreso y aprobada con mayoría simple.", "La cuarta parte de los miembros del Congreso y aprobada con mayoría absoluta.", "La quinta parte de los miembros del Congreso y aprobada con mayoría absoluta."], "bloque": "t5-ce", "precepto": "Artículo 102.2 CE", "correcta": 2, "justificaciones": ["No. La fracción es un cuarto, no un quinto.", "No. La fracción es correcta a medias en otras opciones, pero aquí la mayoría exigida es absoluta, no simple.", "Es esta. Literal del artículo 102.2: la cuarta parte propone, la mayoría absoluta aprueba.", "No. Ni la fracción (quinta parte) ni, si se combinara con la mayoría absoluta sola, coincidiría con el precepto: son exactamente un cuarto y mayoría absoluta."], "arts": [102], "citas": [{"texto": "«La acusación de traición o de cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, sólo podrá ser planteada por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo.»", "fuente": "Artículo 102.2 CE"}], "truco": "No confundir con la moción de censura (décima parte + mayoría absoluta) ni con la reforma constitucional agravada (dos quintos o similar): aquí las cifras propias son un cuarto de los Diputados y mayoría absoluta."}, {"id": "ce-334", "origen": "otras", "test": "Examen Tema 5", "n": 13, "enunciado": "De conformidad con el artículo 104 de la Constitución Española, las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de Seguridad se determinarán mediante:", "opciones": ["Ley ordinaria.", "Ley orgánica.", "Decreto-ley.", "Las leyes de las distintas Comunidades Autónomas."], "bloque": "t5-ce", "precepto": "Artículo 104.2 CE", "correcta": 1, "justificaciones": ["No. La ley ordinaria no basta para esta materia.", "Es esta. Literal del artículo 104.2: reserva de ley orgánica.", "No. El Decreto-ley no puede regular materia reservada a ley orgánica (art. 86.1 CE).", "No. Las Comunidades Autónomas no tienen esta competencia: es materia estatal y de ley orgánica."], "arts": [104], "citas": [{"texto": "«Una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de Seguridad.»", "fuente": "Artículo 104.2 CE"}], "truco": "La reserva de ley orgánica del art.104.2 se suma a la lista corta del art.81.1: desarrollo de derechos fundamentales, Estatutos de Autonomía y régimen electoral general, y «las demás previstas en la Constitución»: aquí, las Fuerzas y Cuerpos de Seguridad."}, {"id": "ce-335", "origen": "otras", "test": "Examen Tema 5", "n": 30, "enunciado": "Según el artículo 106 de la Constitución Española, la legalidad de la actuación administrativa y el sometimiento de ésta a los fines que la justifican, es controlada por:", "opciones": ["El Defensor del Pueblo.", "El Gobierno.", "Las Cortes Generales.", "Los Tribunales."], "bloque": "t5-ce", "precepto": "Artículo 106.1 CE", "correcta": 3, "justificaciones": ["No. El Defensor del Pueblo supervisa la actuación de la Administración, pero no ejerce control jurisdiccional en el sentido del art. 106.", "No. El Gobierno es precisamente el controlado, no el controlador.", "No. Las Cortes Generales ejercen el control político del Gobierno (art. 66.2, 108), distinto del control jurisdiccional del 106.", "Es esta. Literal del artículo 106.1: el control jurisdiccional de la Administración corresponde a los Tribunales."], "arts": [106], "citas": [{"texto": "«Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican.»", "fuente": "Artículo 106.1 CE"}], "truco": "Tres controles distintos sobre la Administración: político (Cortes Generales), jurisdiccional (Tribunales, art.106) y de supervisión sin poder de anulación (Defensor del Pueblo)."}, {"id": "ce-339", "origen": "otras", "test": "Examen Tema 5", "n": 3, "enunciado": "Señala cuál de las siguientes NO es una causa de cese del Gobierno conforme al artículo 101 de la Constitución Española:", "opciones": ["Tras la celebración de elecciones generales.", "En los casos de pérdida de la confianza parlamentaria previstos en la Constitución.", "Por presentación de una moción de censura.", "Por dimisión o fallecimiento de su Presidente."], "bloque": "t5-ce", "precepto": "Artículo 101.1 CE", "correcta": 2, "justificaciones": ["No. Sí es una causa expresa del artículo 101.1.", "No. También lo es, y precisamente engloba la moción de censura CUANDO PROSPERA.", "Es esta. La mera presentación de una moción de censura no cesa al Gobierno: solo su adopción por el Congreso (una de las formas de «pérdida de la confianza parlamentaria») produce ese efecto.", "No. Igualmente es una causa expresa del precepto."], "arts": [101], "citas": [{"texto": "«El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.»", "fuente": "Artículo 101.1 CE"}], "truco": "Presentar una moción de censura no cesa al Gobierno; que se APRUEBE, sí: como forma de pérdida de la confianza parlamentaria del art. 101.1."}, {"id": "ce-340", "origen": "otras", "test": "Examen Tema 5", "n": 8, "enunciado": "De conformidad con la Ley 50/1997, de 27 de noviembre, del Gobierno, corresponde al Consejo de Ministros:", "opciones": ["Proponer al Rey la convocatoria de un referéndum consultivo, previa autorización del Congreso de los Diputados.", "Declarar el estado de sitio, así como proponer al Congreso de los Diputados la declaración del estado de alarma.", "Acordar la negociación y firma de Tratados internacionales, así como su aplicación provisional.", "Crear, modificar y suprimir por Real Decreto los Departamentos Ministeriales, así como las Secretarías de Estado."], "bloque": "t5-ley", "precepto": "Artículo 5.1.d y 5.1.f · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Proponer al Rey el referéndum consultivo es función del Presidente, no del Consejo de Ministros (art. 2.2.e).", "No. Invierte los papeles del 5.1.f: el Consejo de Ministros DECLARA alarma y excepción, y PROPONE al Congreso el estado de sitio: no al revés.", "Es esta. Literal del artículo 5.1.d.", "No. Crear o suprimir Departamentos Ministeriales y Secretarías de Estado es función del Presidente (art. 2.2.j)."], "arts": [], "citas": [{"texto": "«Al Consejo de Ministros … le corresponde el ejercicio de las siguientes funciones: … d) Acordar la negociación y firma de Tratados internacionales, así como su aplicación provisional. … f) Declarar los estados de alarma y de excepción y proponer al Congreso de los Diputados la declaración del estado de sitio.»", "fuente": "Artículo 5.1.d y 5.1.f · Ley 50/1997"}], "truco": "Los tres estados excepcionales no se tratan igual: alarma y excepción los declara directamente el Consejo de Ministros (el de excepción con autorización previa del Congreso); el de sitio lo declara el Congreso, a propuesta del Gobierno."}, {"id": "ce-341", "origen": "otras", "test": "Examen Tema 5", "n": 9, "enunciado": "De conformidad con el artículo 99 de la Constitución Española, el candidato propuesto por el Rey a la Presidencia del Gobierno expondrá el programa político del Gobierno que pretenda formar ante:", "opciones": ["El Rey.", "El Congreso de los Diputados.", "El Senado.", "Las Cortes Generales."], "bloque": "t5-ce", "precepto": "Artículo 99.2 CE", "correcta": 1, "justificaciones": ["No. El Rey propone al candidato, pero no es ante él ante quien se expone el programa.", "Es esta. Literal del artículo 99.2: la exposición del programa y la solicitud de confianza se hacen siempre ante el Congreso.", "No. El Senado no interviene en la investidura.", "No. No son las Cortes Generales conjuntamente, sino el Congreso en solitario."], "arts": [99], "citas": [{"texto": "«El candidato propuesto conforme a lo previsto en el apartado anterior expondrá ante el Congreso de los Diputados el programa político del Gobierno que pretenda formar y solicitará la confianza de la Cámara.»", "fuente": "Artículo 99.2 CE"}], "marca": {"nivel": "estrella", "nota": "La investidura del artículo 99 (plazos, mayorías y los dos meses) está en las listas y ha caído en el INAP."}, "truco": "Toda la investidura (propuesta del Rey, exposición del programa, votación de confianza) gira en torno al Congreso; el Senado queda fuera del proceso."}, {"id": "ce-342", "origen": "otras", "test": "Examen Tema 5", "n": 11, "enunciado": "De conformidad con lo dispuesto en la Ley 50/1997, de 27 de noviembre, del Gobierno, el Presidente del Gobierno en funciones podrá desempeñar una de las siguientes facultades:", "opciones": ["Presentar proyectos de ley al Congreso de los Diputados o, en su caso, al Senado.", "Aprobar el proyecto de ley de Presupuestos Generales del Estado.", "Refrendar, en su caso, los actos del Rey.", "Proponer al Rey la convocatoria de un referéndum consultivo."], "bloque": "t5-ley", "precepto": "Artículo 21.4 · Ley 50/1997; Artículo 21.5 · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Está expresamente vetada al Gobierno en funciones (21.5.b).", "No. También vetada (21.5.a).", "Es esta. Refrendar los actos del Rey (art. 2.2.h) no figura entre las facultades vetadas al Presidente en funciones por el artículo 21: sigue siendo una función ordinaria suya.", "No. Vetada al Presidente en funciones (21.4.c)."], "arts": [], "citas": [{"texto": "«El Presidente del Gobierno en funciones no podrá ejercer las siguientes facultades: a) Proponer al Rey la disolución de alguna de las Cámaras, o de las Cortes Generales. b) Plantear la cuestión de confianza. c) Proponer al Rey la convocatoria de un referéndum consultivo.»", "fuente": "Artículo 21.4 · Ley 50/1997"}, {"texto": "«El Gobierno en funciones no podrá ejercer las siguientes facultades: a) Aprobar el Proyecto de Ley de Presupuestos Generales del Estado. b) Presentar proyectos de ley al Congreso de los Diputados o, en su caso, al Senado.»", "fuente": "Artículo 21.5 · Ley 50/1997"}], "truco": "El Gobierno en funciones limita su gestión al despacho ordinario: pierde la iniciativa legislativa y presupuestaria y la capacidad de disolver Cámaras, plantear confianza o convocar referéndum, pero conserva las funciones de mero trámite constitucional, como el refrendo."}, {"id": "ce-343", "origen": "otras", "test": "Test exámenes", "n": 201, "enunciado": "El artículo 105 de la Constitución Española establece que una Ley regulará:", "opciones": ["El derecho de los ciudadanos a utilizar las lenguas oficiales en el territorio de su Comunidad Autónoma.", "El acceso de los ciudadanos a los archivos y registros administrativos, salvo en lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas.", "El derecho de los ciudadanos a conocer, en cualquier momento, el estado de la tramitación de los procedimientos en los que tengan la condición de interesados.", "El derecho de los ciudadanos a acceder en condiciones de igualdad a las funciones y cargos públicos."], "bloque": "t5-ce", "precepto": "Artículo 105.b CE", "correcta": 1, "justificaciones": ["No. El uso de las lenguas oficiales es materia del artículo 3 CE, no del 105.", "Es esta. Literal del artículo 105.b.", "No. No es la fórmula literal del 105: ese detalle procedimental lo desarrolla la legislación administrativa ordinaria, no el precepto constitucional.", "No. Acceder en condiciones de igualdad a funciones y cargos públicos es un derecho distinto, del artículo 23.2 CE."], "arts": [105], "citas": [{"texto": "«La ley regulará: a) La audiencia de los ciudadanos... b) El acceso de los ciudadanos a los archivos y registros administrativos, salvo en lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas. c) El procedimiento a través del cual deben producirse los actos administrativos, garantizando, cuando proceda, la audiencia del interesado.»", "fuente": "Artículo 105.b CE"}], "truco": "El artículo 105 tiene tres letras: a) audiencia de los ciudadanos en la elaboración de disposiciones administrativas, b) acceso a archivos y registros, y c) procedimiento de los actos administrativos con audiencia del interesado «cuando proceda»."}, {"id": "ce-344", "origen": "otras", "test": "Test exámenes", "n": 219, "enunciado": "De acuerdo con el artículo 105.c de la Constitución Española:", "opciones": ["Una ley orgánica regulará el procedimiento de los actos administrativos, garantizando, cuando proceda, la audiencia del interesado.", "La Ley regulará el procedimiento a través del cual deben producirse los actos administrativos, garantizando, cuando proceda, la audiencia del interesado.", "La Ley regulará el procedimiento a través del cual deben producirse los actos administrativos, garantizando, en todo caso, la audiencia del interesado.", "Una ley orgánica regulará el procedimiento, garantizando, en todo caso, la audiencia del interesado."], "bloque": "t5-ce", "precepto": "Artículo 105.c CE", "correcta": 1, "justificaciones": ["No. No exige ley orgánica: basta la ley ordinaria.", "Es esta. Literal del 105.c: ley ordinaria, y la audiencia se garantiza «cuando proceda», no «en todo caso».", "No. Cambia «cuando proceda» por «en todo caso», endureciendo la garantía más de lo que dice el precepto.", "No. Acumula los dos errores: ni ley orgánica ni «en todo caso»."], "arts": [105], "citas": [{"texto": "«El procedimiento a través del cual deben producirse los actos administrativos, garantizando, cuando proceda, la audiencia del interesado.»", "fuente": "Artículo 105.c CE"}], "truco": "«Cuando proceda», no «en todo caso»: la audiencia del interesado en el procedimiento administrativo admite excepciones regladas por la ley."}, {"id": "ce-345", "origen": "otras", "test": "Test exámenes", "n": 204, "enunciado": "En la Administración General del Estado, de conformidad con el artículo 24.1 de la Ley 50/1997, de 27 de noviembre, del Gobierno, ¿qué forma revisten las decisiones que aprueben normas reglamentarias de la competencia del Consejo de Ministros?", "opciones": ["Reales Decretos Legislativos y Reales Decretos-leyes.", "Órdenes ministeriales.", "Reales Decretos acordados en Consejo de Ministros.", "Reales Decretos del Ministro de la Presidencia."], "bloque": "t5-ley", "precepto": "Artículo 24.1.c · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Esa es la forma de las normas con rango de ley del Gobierno (arts. 82 y 86 CE), no de sus reglamentos.", "No. Las Órdenes Ministeriales son las disposiciones y resoluciones de los Ministros en solitario (24.1.f), no del Consejo de Ministros.", "Es esta. Literal del artículo 24.1.c.", "No. No existe la figura de un Real Decreto del «Ministro de la Presidencia»: los Reales Decretos son del Presidente del Gobierno o del Consejo de Ministros."], "arts": [], "citas": [{"texto": "«Reales Decretos acordados en Consejo de Ministros, las decisiones que aprueben normas reglamentarias de la competencia de éste y las resoluciones que deban adoptar dicha forma jurídica.»", "fuente": "Artículo 24.1.c · Ley 50/1997"}]}, {"id": "ce-346", "origen": "otras", "test": "Test exámenes", "n": 213, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, señale qué corresponde a los Ministros:", "opciones": ["Crear, modificar y suprimir, por Real Decreto, los Departamentos ministeriales.", "Establecer el programa político del Gobierno.", "Ejercer la potestad reglamentaria en las materias propias de su Departamento.", "Fijar el orden del día de las reuniones del Consejo de Ministros."], "bloque": "t5-ley", "precepto": "Artículo 4.1.b · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Crear o suprimir Departamentos Ministeriales es función del Presidente (art. 2.2.j).", "No. Establecer el programa político del Gobierno también es del Presidente (art. 2.2.b).", "Es esta. Literal del artículo 4.1.b.", "No. Fijar el orden del día del Consejo de Ministros corresponde igualmente al Presidente (art. 18.3)."], "arts": [], "citas": [{"texto": "«Los Ministros, como titulares de sus Departamentos, tienen competencia y responsabilidad en la esfera específica de su actuación, y les corresponde el ejercicio de las siguientes funciones: … b) Ejercer la potestad reglamentaria en las materias propias de su Departamento.»", "fuente": "Artículo 4.1.b · Ley 50/1997"}], "truco": "El principio departamental: cada Ministro tiene su propia potestad reglamentaria dentro de su Departamento, distinta de la potestad reglamentaria general que ejerce el Consejo de Ministros (art. 5.1.h)."}, {"id": "ce-347", "origen": "otras", "test": "Test exámenes", "n": 214, "enunciado": "Señale la afirmación correcta en relación con la regulación constitucional del Gobierno:", "opciones": ["El Gobierno se compone del Presidente, de los Vicepresidentes, de los Ministros y de los Secretarios de Estado.", "Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las Leyes.", "El Presidente del Gobierno es nombrado por el Rey, a propuesta del Consejo de Ministros.", "La responsabilidad criminal del Presidente será exigible, en su caso, por el Tribunal Constitucional."], "bloque": "t5-ce", "precepto": "Artículo 97 CE", "correcta": 1, "justificaciones": ["No. Los Secretarios de Estado nunca son miembros del Gobierno.", "Es esta. Literal del artículo 97: es la posición constitucional básica del Gobierno, reproducida además en el artículo 1.1 de la Ley 50/1997.", "No. El Presidente del Gobierno se nombra según el procedimiento de investidura del artículo 99 CE, no a propuesta del Consejo de Ministros: que ni siquiera existe hasta que el Gobierno se forma.", "No. La responsabilidad criminal del Presidente se exige ante la Sala de lo Penal del Tribunal Supremo (art. 102.1 CE), no ante el Tribunal Constitucional."], "arts": [97], "citas": [{"texto": "«El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.»", "fuente": "Artículo 97 CE"}], "marca": {"nivel": "clave", "nota": "Funciones del Gobierno (art. 97) y principios de la Administración (art. 103): en las listas y en el INAP."}}, {"id": "ce-348", "origen": "otras", "test": "Test exámenes", "n": 220, "enunciado": "Conforme al artículo 21 de la Ley 50/1997, de 27 de noviembre, del Gobierno, ¿en cuál de los siguientes casos NO se produce el cese del Gobierno?", "opciones": ["Tras la celebración de elecciones generales.", "Por dimisión de la mitad más uno de sus Ministros.", "En los casos de pérdida de la confianza parlamentaria previstos en la Constitución.", "Por dimisión o fallecimiento de su Presidente."], "bloque": "t5-ley", "precepto": "Artículo 21.1 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Sí es causa expresa.", "Es esta. La lista de causas de cese es cerrada y gira siempre en torno al Presidente o a la confianza parlamentaria: la dimisión de varios Ministros, por numerosos que sean, no está entre ellas.", "No. También lo es.", "No. Igualmente es una causa expresa del precepto."], "arts": [], "citas": [{"texto": "«El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.»", "fuente": "Artículo 21.1 · Ley 50/1997"}], "truco": "Un Ministro dimite y se le sustituye sin que pase nada al Gobierno como tal; solo la dimisión o el fallecimiento del PRESIDENTE hace cesar a todo el Gobierno."}, {"id": "ce-349", "origen": "otras", "test": "Test exámenes", "n": 226, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, señale qué corresponde al Consejo de Ministros:", "opciones": ["Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios.", "Establecer el programa político del Gobierno y determinar las directrices de la política interior y exterior.", "Adoptar programas, planes y directrices vinculantes para todos los órganos de la Administración General del Estado.", "Crear, modificar y suprimir los Departamentos Ministeriales, así como las Secretarías de Estado."], "bloque": "t5-ley", "precepto": "Artículo 5.1.j · Ley 50/1997", "correcta": 2, "justificaciones": ["No. Resolver conflictos entre Ministerios es del Presidente (2.2.l).", "No. Establecer el programa político también es del Presidente (2.2.b).", "Es esta. Literal del artículo 5.1.j.", "No. Crear o suprimir Departamentos y Secretarías de Estado es del Presidente (2.2.j)."], "arts": [], "citas": [{"texto": "«Al Consejo de Ministros … le corresponde el ejercicio de las siguientes funciones: … j) Adoptar programas, planes y directrices vinculantes para todos los órganos de la Administración General del Estado.»", "fuente": "Artículo 5.1.j · Ley 50/1997"}], "truco": "Cuando la opción diga «programas, planes y directrices VINCULANTES PARA TODA LA AGE», piensa en el Consejo de Ministros como órgano colegiado; cuando hable del rumbo político del Gobierno, piensa en el Presidente."}, {"id": "ce-350", "origen": "otras", "test": "Test exámenes", "n": 234, "enunciado": "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, los acuerdos adoptados en las Comisiones Delegadas del Gobierno revestirán la forma de:", "opciones": ["Real Decreto Legislativo.", "Orden del Ministro competente, o del Ministro de la Presidencia cuando afecten a distintos Ministros.", "Acuerdo del Consejo de Ministros.", "Resolución."], "bloque": "t5-ley", "precepto": "Artículo 24.1.e · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Los Reales Decretos Legislativos son la forma de la legislación delegada del Gobierno en pleno (art. 85 CE), no de las Comisiones Delegadas.", "Es esta. Literal del artículo 24.1.e.", "No. El Acuerdo del Consejo de Ministros es la forma propia de ese órgano (24.1.d), no de sus Comisiones Delegadas.", "No. «Resolución» no es la forma jurídica que exige el precepto."], "arts": [], "citas": [{"texto": "«Acuerdos adoptados en Comisiones Delegadas del Gobierno, las disposiciones y resoluciones de tales órganos colegiados. Tales acuerdos revestirán la forma de Orden del Ministro competente o del Ministro de la Presidencia, cuando la competencia corresponda a distintos Ministros.»", "fuente": "Artículo 24.1.e · Ley 50/1997"}], "truco": "Aunque se llamen «Comisiones Delegadas del Gobierno», sus acuerdos no toman forma de Real Decreto: siempre Orden Ministerial, del competente o del de la Presidencia si el asunto es de varios."}, {"id": "ce-351", "origen": "otras", "test": "Test exámenes", "n": 235, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, los proyectos de disposiciones reglamentarias habrán de ser informados por la Secretaría General Técnica del Ministerio o Ministerios proponentes:", "opciones": ["En todo caso.", "Sólo cuando la norma reglamentaria pudiera afectar a la distribución de competencias entre el Estado y las Comunidades Autónomas.", "Cuando lo estime oportuno el órgano directivo que inició su tramitación.", "Cuando no haya informe del Consejo de Estado."], "bloque": "t5-ley", "precepto": "Artículo 26.5 · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 26.5: el informe de la Secretaría General Técnica es siempre preceptivo, sin excepción.", "No. Ese supuesto exige, además, informe del Ministerio de Política Territorial (26.5), pero no convierte en excepcional el informe de la Secretaría General Técnica, que es siempre obligatorio.", "No. No queda al arbitrio del órgano directivo: la ley lo impone «en todo caso».", "No. El informe de la Secretaría General Técnica es independiente del dictamen del Consejo de Estado; ambos pueden ser preceptivos a la vez."], "arts": [], "citas": [{"texto": "«En todo caso, los anteproyectos de ley, los proyectos de real decreto legislativo y los proyectos de disposiciones reglamentarias, deberán ser informados por la Secretaría General Técnica del Ministerio o Ministerios proponentes.»", "fuente": "Artículo 26.5 · Ley 50/1997"}]}, {"id": "ce-352", "origen": "otras", "test": "Test exámenes", "n": 236, "enunciado": "Señale la respuesta correcta en relación con el Gobierno en funciones, conforme a la Ley 50/1997, de 27 de noviembre, del Gobierno:", "opciones": ["El Presidente del Gobierno en funciones podrá plantear la cuestión de confianza.", "Las delegaciones legislativas otorgadas por las Cortes Generales quedarán en suspenso durante todo el tiempo que el Gobierno esté en funciones, como consecuencia de la celebración de elecciones generales.", "El Gobierno en funciones podrá presentar proyectos de Ley al Congreso de los Diputados, pero en ningún caso al Senado.", "El Gobierno en funciones podrá aprobar el Proyecto de Ley de Presupuestos Generales del Estado con autorización de la mayoría absoluta del Congreso."], "bloque": "t5-ley", "precepto": "Artículo 21.6 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. Plantear la cuestión de confianza está expresamente vetado al Presidente en funciones (21.4.b).", "Es esta. Literal del artículo 21.6: la suspensión de las delegaciones legislativas se limita a cuando el Gobierno está en funciones por elecciones generales, no por cualquier otra causa de cese.", "No. No hay excepción a favor del Congreso: el Gobierno en funciones no puede presentar proyectos de ley a ninguna de las dos Cámaras (21.5.b).", "No. No existe ninguna vía de autorización que permita al Gobierno en funciones aprobar el Proyecto de Presupuestos: está vetado sin excepción (21.5.a)."], "arts": [], "citas": [{"texto": "«Las delegaciones legislativas otorgadas por las Cortes Generales quedarán en suspenso durante todo el tiempo que el Gobierno esté en funciones como consecuencia de la celebración de elecciones generales.»", "fuente": "Artículo 21.6 · Ley 50/1997"}], "truco": "La suspensión de las delegaciones legislativas del art. 21.6 solo opera cuando el Gobierno entra en funciones por elecciones generales, no cuando lo hace por dimisión del Presidente, por pérdida de confianza o por su fallecimiento."}, {"id": "ce-353", "origen": "otras", "test": "Test exámenes", "n": 237, "enunciado": "A tenor de lo dispuesto en la Ley 50/1997, de 27 de noviembre, del Gobierno, elaborado el texto de un reglamento que afecte a los derechos e intereses legítimos de los ciudadanos, se les dará audiencia, con carácter general, durante un plazo razonable y no inferior a:", "opciones": ["10 días hábiles.", "15 días hábiles.", "10 días naturales.", "30 días hábiles."], "bloque": "t5-ley", "precepto": "Artículo 26.6 · Ley 50/1997", "correcta": 1, "justificaciones": ["No. 10 días hábiles no es la cifra general del precepto.", "Es esta. Literal del artículo 26.6: 15 días hábiles como mínimo general, reducible hasta 7 solo por razones justificadas.", "No. El plazo se cuenta en días hábiles, no naturales.", "No. 30 días hábiles es un plazo distinto: el de la consulta pública previa a la redacción del texto (art. 26.2), que se cuenta en días naturales y con un mínimo de quince."], "arts": [], "citas": [{"texto": "«El plazo mínimo de esta audiencia e información públicas será de 15 días hábiles, y podrá ser reducido hasta un mínimo de siete días hábiles cuando razones debidamente motivadas así lo justifiquen.»", "fuente": "Artículo 26.6 · Ley 50/1997"}], "truco": "No confundir la consulta pública PREVIA a redactar la norma (mínimo 15 días naturales, art. 26.2) con la audiencia e información pública sobre el texto YA REDACTADO (mínimo 15 días hábiles, reducible a 7, art. 26.6)."}, {"id": "ce-354", "origen": "otras", "test": "Test exámenes", "n": 242, "enunciado": "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, es competencia de los Ministros:", "opciones": ["Refrendar, en su caso, los actos del Rey en materias de su competencia.", "Interponer el recurso de inconstitucionalidad si la materia afecta a su Departamento Ministerial.", "Fijar el orden del día de las reuniones del Consejo de Ministros siguiendo un orden rotatorio.", "Plantear ante el Congreso la cuestión de confianza."], "bloque": "t5-ley", "precepto": "Artículo 4.1.d · Ley 50/1997", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 4.1.d: cada Ministro refrenda los actos del Rey solo en lo que toca a su propio Departamento; el refrendo general lo ejerce el Presidente (art. 2.2.h).", "No. Interponer el recurso de inconstitucionalidad corresponde en exclusiva al Presidente del Gobierno (2.2.i), no a cada Ministro por su materia.", "No. El orden del día del Consejo de Ministros lo fija siempre el Presidente (18.3), sin rotación entre Ministros.", "No. Plantear la cuestión de confianza es función exclusiva del Presidente (2.2.d)."], "arts": [], "citas": [{"texto": "«Refrendar, en su caso, los actos del Rey en materia de su competencia.»", "fuente": "Artículo 4.1.d · Ley 50/1997"}], "truco": "Hay dos niveles de refrendo: el Presidente refrenda con carácter general (2.2.h); cada Ministro refrenda, además, en lo que afecte específicamente a su propio Departamento (4.1.d)."}, {"id": "ce-355", "origen": "otras", "test": "Test exámenes", "n": 246, "enunciado": "De acuerdo con la Ley 50/1997, de 27 de noviembre, del Gobierno, corresponde a las Comisiones Delegadas, como órganos colegiados del Gobierno:", "opciones": ["Aprobar los proyectos de ley y su remisión al Congreso de los Diputados o, en su caso, al Senado.", "Aprobar el Proyecto de Ley de Presupuestos Generales del Estado.", "Aprobar los reglamentos para el desarrollo y ejecución de las leyes, previo dictamen del Consejo de Estado.", "Estudiar aquellos asuntos que, afectando a varios Ministerios, requieran la elaboración de una propuesta conjunta previa a su resolución por el Consejo de Ministros."], "bloque": "t5-ley", "precepto": "Artículo 6.4.b · Ley 50/1997", "correcta": 3, "justificaciones": ["No. Aprobar proyectos de ley y remitirlos a las Cortes es función exclusiva del Consejo de Ministros en pleno (5.1.a).", "No. Aprobar los Presupuestos también es del Consejo de Ministros en pleno (5.1.b).", "No. Aprobar reglamentos con dictamen del Consejo de Estado igualmente corresponde al Consejo de Ministros (5.1.h).", "Es esta. Literal del artículo 6.4.b."], "arts": [], "citas": [{"texto": "«Corresponde a las Comisiones Delegadas, como órganos colegiados del Gobierno: … b) Estudiar aquellos asuntos que, afectando a varios Ministerios, requieran la elaboración de una propuesta conjunta previa a su resolución por el Consejo de Ministros.»", "fuente": "Artículo 6.4.b · Ley 50/1997"}], "truco": "Las Comisiones Delegadas preparan y filtran (examinan cuestiones generales, elaboran propuestas conjuntas, resuelven lo que no necesita subir más arriba), pero las grandes decisiones (leyes, Presupuestos, reglamentos de desarrollo) las reserva la Ley al Consejo de Ministros en pleno."}, {"id": "ce-356", "origen": "otras", "test": "Test exámenes", "n": 247, "enunciado": "De conformidad con el artículo 113 de la Constitución Española, señale cuál de las siguientes afirmaciones sobre la moción de censura es correcta:", "opciones": ["Deberá ser propuesta al menos por cincuenta Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.", "No podrá ser votada hasta que transcurran dos días desde su presentación.", "Se adoptará por mayoría absoluta del Congreso de los Diputados.", "Si la moción de censura no fuera aprobada por el Congreso, sus signatarios podrán presentar otra durante el mismo periodo de sesiones."], "bloque": "t5-ce", "precepto": "Artículo 113 CE; Artículo 113.4 CE", "correcta": 2, "justificaciones": ["No. El umbral es la décima parte de los Diputados, no una cifra fija de cincuenta.", "No. El plazo de espera es de cinco días, no de dos.", "Es esta. La adopción exige mayoría absoluta del Congreso (113.1), correcta sin matices.", "No. Es justo lo contrario: el artículo 113.4 prohíbe expresamente a los mismos signatarios firmar otra moción en el mismo periodo de sesiones si la primera fue rechazada."], "arts": [113], "citas": [{"texto": "«La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno. […] La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación. […] Si la moción de censura fuera aprobada por el Congreso de los Diputados, el Presidente del Gobierno presentará su dimisión al Rey.»", "fuente": "Artículo 113 CE"}, {"texto": "«Ninguno de los signatarios de una moción de censura que resulte rechazada podrá firmar otra durante el mismo período de sesiones.»", "fuente": "Artículo 113.4 CE"}], "marca": {"nivel": "clave", "nota": "La moción de censura: proponerla, votarla y qué pasa si sale."}, "truco": "La moción rechazada «quema» a sus firmantes para ese periodo de sesiones: es una cláusula anti-obstrucción para que no se repita la censura una y otra vez con las mismas firmas."}, {"id": "ce-358", "origen": "otras", "test": "Examen Temas 1-5", "n": 22, "enunciado": "El Rey podrá presidir las sesiones del Consejo de Ministros:", "opciones": ["Cuando el Rey, por razones de interés general, así lo decida.", "A petición del Pleno del Consejo de Ministros.", "A petición del Presidente del Gobierno.", "No está prevista constitucionalmente la presidencia del Consejo de Ministros por parte del Rey."], "bloque": "t5-ce", "precepto": "Artículo 62.g CE", "correcta": 2, "justificaciones": ["No. El Rey no decide por sí solo: necesita la petición del Presidente del Gobierno.", "No. No es el Pleno del Consejo de Ministros quien lo pide, sino específicamente su Presidente.", "Es esta. Literal del artículo 62.g: el Rey preside para ser informado, y siempre a petición del Presidente del Gobierno, nunca por iniciativa propia ni de todo el Consejo.", "No. Sí está prevista, precisamente en el artículo 62.g CE."], "arts": [62], "citas": [{"texto": "«Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno.»", "fuente": "Artículo 62.g CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Cuando el Rey preside, el Consejo de Ministros pasa a tener carácter meramente informativo para él; no vota ni decide en ese papel de presidente honorífico."}, {"id": "ce-359", "origen": "otras", "test": "Examen Temas 1-5", "n": 25, "enunciado": "En caso de dimisión del Presidente del Gobierno:", "opciones": ["El Gobierno cesa a continuación.", "El Pleno del Congreso, por mayoría absoluta, podrá proponer al Rey un nuevo candidato a la Presidencia del Gobierno.", "El Pleno del Congreso y del Senado, por mayoría absoluta, podrán proponer conjuntamente al Rey un nuevo candidato.", "El Gobierno continúa con plenas competencias hasta la investidura de un nuevo Presidente."], "bloque": "t5-ce", "precepto": "Artículo 101.1 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 101.1: la dimisión del Presidente es, por sí sola, una de las tres causas de cese de todo el Gobierno.", "No. El Congreso no propone candidatos por iniciativa propia: es el Rey quien propone, tras consultar a los grupos parlamentarios (art. 99.1).", "No. Tampoco existe esa vía conjunta Congreso-Senado.", "No. El Gobierno cesante continúa solo EN FUNCIONES, con las limitaciones del artículo 21 de la Ley 50/1997, no con plenas competencias."], "arts": [101], "citas": [{"texto": "«El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.»", "fuente": "Artículo 101.1 CE"}], "truco": "Dimisión del Presidente → cesa todo el Gobierno (101.1) → el cesante continúa en funciones (21.2 Ley 50/1997) hasta que un nuevo Presidente resulte investido por el procedimiento del artículo 99."}, {"id": "ce-364", "origen": "otras", "test": "Examen Tema 4", "n": 25, "enunciado": "En virtud del artículo 92 de la Constitución Española, las decisiones políticas de especial trascendencia podrán ser sometidas a referéndum consultivo de todos los ciudadanos. El referéndum será convocado:", "opciones": ["Por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso de los Diputados.", "Por el Presidente del Gobierno, a propuesta del Congreso.", "Por las Cortes Generales.", "Por las Cortes Generales, a propuesta del Consejo de Ministros."], "bloque": "t5-ce", "precepto": "Artículo 92.2 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 92.2: tres pasos encadenados: propone el Presidente, autoriza el Congreso, convoca el Rey.", "No. El Presidente propone, pero no convoca; y no es el Congreso quien inicia la propuesta.", "No. Las Cortes Generales no convocan el referéndum consultivo.", "No. Tampoco lo convocan a propuesta del Consejo de Ministros: el orden correcto es Presidente → Congreso → Rey."], "arts": [92], "citas": [{"texto": "«El referéndum será convocado por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso de los Diputados.»", "fuente": "Artículo 92.2 CE"}], "truco": "Compárese con la propuesta al Rey de un referéndum consultivo entre las funciones del Presidente del Gobierno (art. 2.2.e Ley 50/1997): la misma cadena de tres pasos, vista ahora desde la Ley del Gobierno."}]});
